static uint64_t sum_tree(Word node) {
  return node ? unbox(load(node, 0)) + sum_tree(load(node, 1)) + sum_tree(load(node, 2)) : 0;
}
static void selftest(const char *only) {
  Word a = 0, b = 0; Root ra, rb;
